 private static int checks;private static Path dll;
 private static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
 private interface Work{void run()throws Exception;}private static void reject(Work work,String text)throws Exception{boolean yes=false;try{work.run();}catch(IOException expected){yes=expected.getMessage().contains(text);}check(yes,"precise "+text);}
 private interface Save{void save(DataOutput out)throws IOException;}private static byte[] save(Save save)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();save.save(new DataOutputStream(out));return out.toByteArray();}private static DataInput input(byte[] raw){return new DataInputStream(new ByteArrayInputStream(raw));}
