   source.words.unknown(Pc1OsWords.FONT12,"unrelated raw font is unknown");int first=source.words.rawWord(Pc1OsWords.SOURCE_DC),second=source.words.rawWord(Pc1OsWords.DESTINATION_DC);source.words.rawWord(Pc1OsWords.SOURCE_DC,second);source.bus.writeAddress(Pc1WindowMemory.BITMAP_INFO+14,32);Pc1WindowsWindow.State state=original.snapshotPhysical(source.pool);byte[] capsule=save(state::save);state=Pc1WindowsWindow.State.load(input(capsule));check(Arrays.equals(capsule,save(state::save))&&state.dibPoolLeaseIndex()==0&&!state.ownsOrphanDibPayload()&&capsule.length<ddb.length+100000,"P1W1 references sole Pool DIB and owns full DDB once");byte[] pool=save(source.pool::save),words=save(source.words::save),memory=save(source.memory::save),registry=save(source.registry::save);Pc1ImagePool.Image image=Pc1ImagePool.loadImage(input(pool));Pc1GuestAddressSpace.Image layout=image.guestLayout();
   World cancelled=new World(layout);Display cancelDisplay=new Display();try(Pc1WindowsWindow abort=Pc1WindowsWindow.stagePhysical(dll,cancelDisplay,cancelled.words,state,original.adoptHwnd())){check(cancelDisplay.callbacks==0&&original.windowInfo()[0]==1,"staging allocates no HWND or engine initialization/paint messages");reject(()->abort.setTimer(91,100),"not activated");abort.completePhysicalRestore(null);}check(original.windowInfo()[0]==1&&oldDib.live(),"abort preserves adopted source HWND and original DIB lifetime");
   //Mutate current physical pixels after capture: reconstruction uses the
