   byte[] face={(byte)0xba,(byte)0xda,(byte)0xcc,(byte)0xe5,0};sf.fonts.font(Pc1OsWords.FONT28,sf.fonts.createFont(56,28,face));sf.glyph=sf.fonts.initialize404230(original.hwnd(),sf.memory);long ownFirst=original.bootstrapHandles()[1];source.words.rawWord(Pc1OsWords.GLYPH_DC,source.words.rawWord(Pc1OsWords.SOURCE_DC));original.configureDcCapsuleAudit(2);original.configureDcCapsuleAudit(3);byte[] expected=sf.glyph.outline(new byte[]{65},0,28).monoBytesChecked();sf.fonts.font(Pc1OsWords.FONT40,sf.fonts.createFont(80,40,face));source.words.rawWord(Pc1OsWords.FONT28,source.words.rawWord(Pc1OsWords.FONT40));check(original.ownedDcSelections(2)[0]!=sf.fonts.font(Pc1OsWords.FONT28),"actual aliased Window DC keeps old28 font independently from current raw FONT28->40");
